    { id=20254, tab=3, tier=4, col=3, name="Focused Mind", icon="spell_nature_focusedmind", maxRank=3, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Reduces the duration of any Silence or Interrupt effects used against the Shaman by 10%. This effect does not stack with other similar effects.", "Reduces the duration of any Silence or Interrupt effects used against the Shaman by 20%. This effect does not stack with other similar effects.", "Reduces the duration of any Silence or Interrupt effects used against the Shaman by 30%. This effect does not stack with other similar effects." }, localized={deDE={name="Fokussierte Gedanken", tooltip={ "Verringert die Dauer aller gegen den Schamanen eingesetzten Stille- oder Unterbrechungseffekte um 10%. Dieser Effekt ist nicht mit anderen ähnlichen Effekten stapelbar.", "Verringert die Dauer aller gegen den Schamanen eingesetzten Stille- oder Unterbrechungseffekte um 20%. Dieser Effekt ist nicht mit anderen ähnlichen Effekten stapelbar.", "Verringert die Dauer aller gegen den Schamanen eingesetzten Stille- oder Unterbrechungseffekte um 30%. Dieser Effekt ist nicht mit anderen ähnlichen Effekten stapelbar." }}} },
    { id=20255, tab=3, tier=5, col=2, name="Purification", icon="spell_frost_wizardmark", maxRank=5, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Increases the effectiveness of your healing spells by 2%.", "Increases the effectiveness of your healing spells by 4%.", "Increases the effectiveness of your healing spells by 6%.", "Increases the effectiveness of your healing spells by 8%.", "Increases the effectiveness of your healing spells by 10%." }, localized={deDE={name="Läuterung", tooltip={ "Erhöht die Wirksamkeit Eurer Heilzauber um 2%.", "Erhöht die Wirksamkeit Eurer Heilzauber um 4%.", "Erhöht die Wirksamkeit Eurer Heilzauber um 6%.", "Erhöht die Wirksamkeit Eurer Heilzauber um 8%.", "Erhöht die Wirksamkeit Eurer Heilzauber um 10%." }}} },
    { id=20256, tab=3, tier=6, col=1, name="Mana Tide Totem", icon="spell_frost_summonwaterelemental", maxRank=1, prereqTalent=20250, prereqPoints=30, wired=true, tooltip={ "Summons a Mana Tide Totem with 5 health at the feet of the caster for 12 sec that restores 6% of total mana every 3 seconds to group members within 30 yards." }, grant={ [1]=947340 }, localized={deDE={name="Totem der Manaflut", tooltip={ "Beschwört zu Füßen des Zaubernden für 12 Sek. ein Totem der Manaflut mit 5 Gesundheit, das Gruppenmitgliedern im Umkreis von 30 Metern alle 3 Sek. 6% ihres gesamten Manas wiederherstellt." }}} },
    { id=20257, tab=3, tier=6, col=2, name="Nature's Guardian", icon="spell_nature_natureguardian", maxRank=5, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Whenever a damaging attack is taken that reduces you below 30% health, you have a 10% chance to heal 10% of your total health and reduce your threat level on that target. 5 second cooldown.", "Whenever a damaging attack is taken that reduces you below 30% health, you have a 20% chance to heal 10% of your total health and reduce your threat level on that target. 5 second cooldown.", "Whenever a damaging attack is taken that reduces you below 30% health, you have a 30% chance to heal 10% of your total health and reduce your threat level on that target. 5 second cooldown.", "Whenever a damaging attack is taken that reduces you below 30% health, you have a 40% chance to heal 10% of your total health and reduce your threat level on that target. 5 second cooldown.", "Whenever a damaging attack is taken that reduces you below 30% health, you have a 50% chance to heal 10% of your total health and reduce your threat level on that target. 5 second cooldown." }, localized={deDE={name="Wächter der Natur", tooltip={ "Wenn Ihr einen Schadensangriff erleidet, der Eure Gesundheit unter 30% senkt, habt Ihr eine Chance von 10%, 10% Eurer gesamten Gesundheit zu heilen und Eure Bedrohung bei diesem Ziel zu verringern. 5 Sek. Abklingzeit.", "Wenn Ihr einen Schadensangriff erleidet, der Eure Gesundheit unter 30% senkt, habt Ihr eine Chance von 20%, 10% Eurer gesamten Gesundheit zu heilen und Eure Bedrohung bei diesem Ziel zu verringern. 5 Sek. Abklingzeit.", "Wenn Ihr einen Schadensangriff erleidet, der Eure Gesundheit unter 30% senkt, habt Ihr eine Chance von 30%, 10% Eurer gesamten Gesundheit zu heilen und Eure Bedrohung bei diesem Ziel zu verringern. 5 Sek. Abklingzeit.", "Wenn Ihr einen Schadensangriff erleidet, der Eure Gesundheit unter 30% senkt, habt Ihr eine Chance von 40%, 10% Eurer gesamten Gesundheit zu heilen und Eure Bedrohung bei diesem Ziel zu verringern. 5 Sek. Abklingzeit.", "Wenn Ihr einen Schadensangriff erleidet, der Eure Gesundheit unter 30% senkt, habt Ihr eine Chance von 50%, 10% Eurer gesamten Gesundheit zu heilen und Eure Bedrohung bei diesem Ziel zu verringern. 5 Sek. Abklingzeit." }}} },
    { id=20258, tab=3, tier=7, col=1, name="Nature's Blessing", icon="spell_nature_natureblessing", maxRank=3, prereqTalent=0, prereqPoints=35, wired=true, tooltip={ "Increases your spell damage and healing by an amount equal to 10% of your Intellect.", "Increases your spell damage and healing by an amount equal to 20% of your Intellect.", "Increases your spell damage and healing by an amount equal to 30% of your Intellect." }, localized={deDE={name="Segen der Natur", tooltip={ "Erhöht Euren Zauberschaden und Eure Heilung um einen Betrag in Höhe von 10% Eurer Intelligenz.", "Erhöht Euren Zauberschaden und Eure Heilung um einen Betrag in Höhe von 20% Eurer Intelligenz.", "Erhöht Euren Zauberschaden und Eure Heilung um einen Betrag in Höhe von 30% Eurer Intelligenz." }}} },
    { id=20259, tab=3, tier=7, col=2, name="Improved Chain Heal", icon="spell_nature_healingwavegreater", maxRank=2, prereqTalent=0, prereqPoints=35, wired=true, tooltip={ "Increases the amount healed by your Chain Heal spell by 10%.", "Increases the amount healed by your Chain Heal spell by 20%." }, localized={deDE={name="Verbesserte Kettenheilung", tooltip={ "Erhöht die durch Euren Zauber 'Kettenheilung' geheilte Menge um 10%.", "Erhöht die durch Euren Zauber 'Kettenheilung' geheilte Menge um 20%." }}} },
    { id=20260, tab=3, tier=8, col=1, name="Earth Shield", icon="spell_nature_skinofearth", maxRank=1, prereqTalent=20258, prereqPoints=40, wired=true, tooltip={ "Protects the target with an earthen shield, giving a 30% chance of ignoring spell interruption when damaged and causing attacks to heal the shielded target for 150. This effect can only occur once every few seconds. 6 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time and only one Elemental Shield can be active on a target at a time." }, grant={ [1]=946537 }, localized={deDE={name="Erdschild", tooltip={ "Schützt das Ziel mit einem Erdschild, der eine Chance von 30% gewährt, durch Schaden verursachte Zauberunterbrechungen zu ignorieren, und Angriffe das geschützte Ziel um 150 heilen lässt. Dieser Effekt kann nur einmal alle paar Sekunden auftreten. 6 Aufladungen. Hält 10 Min. lang an. 'Erdschild' kann jeweils nur auf einem Ziel liegen, und auf einem Ziel kann jeweils nur ein Elementarschild aktiv sein." }}} },
